window.AUTH=window.AUTH||{};window.AUTH["17-1657"]={"d":"17-1657","id":"2018/17-1657","n":"Mission Product Holdings, Inc. v. Tempnology, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner Mission Product Holdings, Inc.","date":"2018-12-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/74715/20181210195312218_17-1657%20ts.pdf","side":"pet","n":41},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-12-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/76566/20181217183017205_17-1657tsacUnitedStates.pdf","side":"us","n":44},{"k":"respondent","label":"Brief of respondent Tempnology, LLC, n/k/a Old Cold LLC","date":"2019-01-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/78978/20190109213804671_No.%2017-1657bs.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Mission Product Holdings, Inc.","date":"2019-02-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1657/87659/20190208134723203_17-1657%20rb.pdf","side":"pet","n":17}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1657_4f15.pdf","tr":true,"items":[{"t":"case","label":"2Die4Kourt v. Hillair Capital Management, LLC","cite":"2016 WL 4487895","y":2016,"court":"C.D. Cal. Aug. 23","by":{"0":"40"}},{"t":"case","label":"A&L Laboratories, Inc. v. Bou-Matic LLC","cite":"429 F.3d 775","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/429/775/","by":{"0":"38"}},{"t":"case","label":"American Express Co. v. Italian Colors Restaurant","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"by":{"0":"56"},"q":[{"src":"brief","b":0,"text":"[n]o legislation pursues its purposes at all costs,’","cite":"570 U.S. 228, 234"}]},{"t":"case","label":"ARP Films, Inc. v. Marvel Entertainment Group, Inc.","cite":"952 F.2d 643","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/952/643/","by":{"0":"40"}},{"t":"case","label":"Associates Commercial Corp. v. Rash","cite":"520 U.S. 953","y":1997,"id":"1996/96-454","sc":1,"by":{"0":"23"}},{"t":"case","label":"Barcamerica International USA Trust v. Tyfield Importers, Inc.","cite":"289 F.3d 589","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/589/","by":{"0":"51, 54"},"q":[{"src":"brief","b":0,"text":"‘quality control of the goods and services sold under the trademark by the licensee’","cite":"289 F.3d 589, 595"}]},{"t":"case","label":"BFP v. Resolution Trust Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"by":{"0":"20"}},{"t":"case","label":"Board of Trade of City of Chicago v. Johnson","cite":"264 U.S. 1","y":1924,"id":"scdb/1923-054","sc":1,"by":{"0":"4, 24, 25, 29, 37","2":"46, 47","3":"5, 16, 18"}},{"t":"case","label":"Boscorale Operating, LLC v. Nautica Apparel, Inc.","cite":"749 N.Y.S.2d 233","y":2002,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/749/233/","by":{"0":"40"}},{"t":"case","label":"Brown v. Marquette Savings & Loan Ass’n","cite":"686 F.2d 608","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/686/608/","by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"be an indication that [the] subsequent amendment is intended to clarify, rather than change, the existing law.","cite":"686 F.2d 608, 615"}]},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"by":{"0":"20","3":"7"}},{"t":"case","label":"Central States, Southeast & Southwest Areas Pension Fund v. Basic American Industries, Inc.","cite":"252 F.3d 911","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/911/","by":{"0":"18"}},{"t":"case","label":"Page(s) City of Oklahoma City v. Tuttle","cite":"471 U.S. 808","y":1985,"id":"1984/83-1919","sc":1,"by":{"0":"42"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"0":"55"}},{"t":"case","label":"College Savings Bank v. Florida Prepaid Postsecondary Education Expense Board","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"by":{"0":"36","2":"54"},"q":[{"src":"brief","b":2,"text":"[t]he hallmark of a protected property interest is the right to exclude others.","cite":"527 U.S. 666, 673"}]},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"by":{"0":"16, 27"}},{"t":"case","label":"Davis v. Blige","cite":"505 F.3d 90","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/505/90/","by":{"0":"43"}},{"t":"case","label":"Donnell v. Herring-Hall-Marvin Safe Co.","cite":"208 U.S. 267","y":1908,"id":"scdb/1907-071","sc":1,"by":{"0":"38"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"by":{"0":"19"}},{"t":"case","label":"Page(s) K Mart Corp. v. Cartier, Inc.","cite":"485 U.S. 176","y":1988,"url":"https://supreme.justia.com/cases/federal/us/485/176/","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Kentucky Fried Chicken Corp. v. Diversified Packaging Corp.","cite":"549 F.2d 368","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/549/368/","by":{"0":"53"}},{"t":"case","label":"L.L. Brown Paper Co. v. Hydroiloid, Inc.","cite":"118 F.2d 674","y":1941,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/118/674/","by":{"0":"43"}},{"t":"case","label":"Leasing Service Corp. v. First Tennessee Bank National Ass’n","cite":"826 F.2d 434","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/826/434/","by":{"0":"29"}},{"t":"case","label":"Lubrizol Enterprises v. Richmond Metal Finishers, Inc.","cite":"756 F.2d 1043","y":1985,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/756/1043/","by":{"0":"13, 29, 30, 31, 33, 49","1":"6, 12, 28","2":"passim","3":"8"},"q":[{"src":"brief","b":0,"text":"deprive [the licensee] of all rights to the [metal-coating] process","cite":"756 F.2d at 1048"},{"src":"argument","who":"Ms. Spinelli","text":"It is certainly true that Congress made an advertent decision to leave trademarks out of 365(n), but the legislative history makes it very clear that, in enacting 365(n), Congress did so because it thought the rule of Lubrizol, which is that rejection deprives the counterparty of rights already conveyed under the agreement, was wrong."},{"src":"argument","who":"Ms. Spinelli","text":"But it did completely repudiate the Lubrizol rule."},{"src":"argument","who":"Ms. Spinelli","text":"And that's precisely at issue in Lubrizol. It did -- it did, in addition, go on to set out a specific federal regime governing subsidiary issues that arise with respect to the relationship between the licensee and the licensor following rejection."}]},{"t":"case","label":"NLRB v. Bildisco & Bildisco","cite":"465 U.S. 513","y":1984,"id":"1983/82-818","sc":1,"by":{"0":"17, 18, 55","1":"4, 5, 16, 20","2":"passim","3":"7, 13"},"q":[{"src":"brief","b":0,"text":"on which performance is due to some extent on both sides.","cite":"465 U.S. 513, 522 n.6"},{"src":"brief","b":0,"text":"to the basic purpose [of] a Chapter 11 reorganization, because rejection can release the debtor’s estate from burdensome obligations that can impede a successful reorganization.","cite":"465 U.S. at 528"},{"src":"brief","b":1,"text":"performance remains due to some extent on both sides.","cite":"465 U.S. 513, 522 n.6"},{"src":"brief","b":2,"text":"suit may not be brought against the debtor-in-possession under the * * * agreement; recovery may be had only through administration of the claim in bankruptcy.","cite":"465 U.S. at 530, 532"},{"src":"brief","b":2,"text":"could not have [been] employed absent the bankruptcy filing.","cite":"465 U.S. at 528"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"performance remains due to some extent on both sides.","cite":"465 U. S. 513, 522, n. 6"}]},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"by":{"0":"47"}},{"t":"case","label":"Ortho Pharmaceutical Corp. v. Genetics Institute, Inc.","cite":"52 F.3d 1026","y":1995,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/52/1026/","by":{"0":"43"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"0":"47","2":"39, 40, 50","3":"15"},"q":[{"src":"brief","b":0,"text":"a statutory scheme in which the specific provision embraced within a general one is not superfluous, because it creates a socalled safe harbor.","cite":"566 U.S. at 647"},{"src":"brief","b":2,"text":"the superfluity of a specific provision that is swallowed by the general [rule].","cite":"566 U.S. 639, 645"},{"src":"brief","b":2,"text":"obligation to interpret the Code clearly and predictably using well established principles of statutory construction.","cite":"566 U.S. at 649"},{"src":"brief","b":3,"text":"‘It is a commonplace of statutory construction that the specific governs the general.’","cite":"566 U.S. 639, 645"}]},{"t":"case","label":"Raleigh v. Illinois Department of Revenue","cite":"530 U.S. 15","y":2000,"id":"1999/99-387","sc":1,"by":{"0":"20","2":"50"},"q":[{"src":"brief","b":0,"text":"‘basic federal rule’ in bankruptcy … that state law governs the substance of claims.","cite":"530 U.S. 15, 20"},{"src":"brief","b":2,"text":"Bankruptcy courts are not authorized in the name of equity to make wholesale substitution of underlying law controlling the validity of creditors’ entitlements, but are limited to what the Bankruptcy Code itself provides.","cite":"530 U.S. 15, 24-25"}]},{"t":"case","label":"S&R Corp. v. Jiffy Lube International Inc.","cite":"968 F.2d 371","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/968/371/","by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"either stop [its own] performance and assume the contract is avoided, or continue its performance and sue for damages.","cite":"968 F.2d 371, 376"}]},{"t":"case","label":"Sanofi, S.A. v. Med-Tech Veterinarian Products, Inc.","cite":"565 F. Supp. 931","y":1983,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./565/931/","by":{"0":"44"}},{"t":"case","label":"Page(s) Sunbeam Products, Inc. v. Chicago American Manufacturing, LLC","cite":"686 F.3d 372","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/686/372/","by":{"0":"passim","1":"9, 11, 14, 17, 31","2":"passim","3":"2"},"q":[{"src":"brief","b":1,"text":"the consequences of rejection of an executory contract under § 365(g).","cite":"686 F.3d 372"},{"src":"brief","b":1,"text":"nothing about this process implies that any rights of the other contracting party have been vaporized.","cite":"686 F.3d at 377"},{"src":"brief","b":3,"text":"[o]utside of bankruptcy, a licensor’s breach does not terminate a licensee’s right to use intellectual property,","cite":"686 F.3d 372, 376-377"}]},{"t":"case","label":"Thompkins v. Lil’ Joe Records, Inc.","cite":"476 F.3d 1294","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/476/1294/","by":{"0":"22, 26","1":"18"},"q":[{"src":"brief","b":0,"text":"has absolutely no effect upon the contract’s continued existence; the contract is not cancelled, repudiated, rescinded, or in any other fashion terminated.’","cite":"476 F.3d 1294, 1306"},{"src":"brief","b":0,"text":"previously carried out by the rejected contract.","cite":"476 F.3d at 1306"},{"src":"brief","b":1,"text":"render[] void the contract and requir[e] that the parties be put back in the positions they occupied before the contract was formed.","cite":"476 F.3d 1294, 1306"}]},{"t":"case","label":"Travelers Casualty & Surety Co. of America v. Pacific Gas & Electric Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"by":{"0":"3, 20"},"q":[{"src":"brief","b":0,"text":"‘basic federal rule’ in bankruptcy … that state law governs the substance of claims.","cite":"549 U.S. 443, 450"}]},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"A common idiom describes property as a ‘bundle of sticks.’ … State law determines only which sticks are in a person’s bundle. Whether those sticks qualify as ‘property’ for purposes of [a] federal … statute is a question of federal law.","cite":"535 U.S. 274, 278-279"}]},{"t":"case","label":"Vanston Bondholders Protective Committee v. Green","cite":"329 U.S. 156","y":1946,"id":"scdb/1946-010","sc":1,"by":{"0":"20"}},{"t":"case","label":"Viacom International, Inc. v. YouTube, Inc.","cite":"676 F.3d 19","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/676/19/","by":{"0":"48"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(35A)","(5)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"45","1":"4, 16, 4, 16","2":"4, 4, 4","3":"5"},"q":[{"src":"brief","b":2,"text":"right to an equitable remedy for breach of performance if such breach gives rise to a right to payment.","cite":"11 U.S.C. 101(5)"}]},{"t":"usc","label":"15 U.S.C. § 1055","url":"https://www.law.cornell.edu/uscode/text/15/1055","stext":{"head":"§1055. Use by related companies affecting validity and registration","paras":[[0,"Where a registered mark or a mark sought to be registered is or may be used legitimately by related companies, such use shall inure to the benefit of the registrant or applicant for registration, and such use shall not affect the validity of such mark or of its registration, provided such mark is not used in such manner as to deceive the public. If first use of a mark by a person is controlled by the registrant or applicant for registration of the mark with respect to the nature and quality of the goods or services, such first use shall inure to the benefit of the registrant or applicant, as the case may be."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1055?type=usc&year=mostrecent&link-type=html"},"by":{"0":"51","2":"9, 45, 54"},"q":[{"src":"brief","b":2,"text":"shall inure to the benefit of the [trademark] registrant.","cite":"15 U.S.C. 1055"},{"src":"brief","b":2,"text":"the nature and quality of the goods or services","cite":"15 U.S.C. 1055, 1127"}]},{"t":"usc","label":"28 U.S.C. § 959","url":"https://www.law.cornell.edu/uscode/text/28/959","by":{"0":"52"}},{"t":"usc","label":"35 U.S.C. § 154","url":"https://www.law.cornell.edu/uscode/text/35/154","by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"the right to exclude others from making, using, … or selling [its] invention throughout the United States.","cite":"35 U.S.C. §154(a)(1)"}]},{"t":"case","label":"American Brake Shoe & Foundry Co. v. New York Rys. Co.","cite":"278 F. 842","y":1922,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./278/842/","by":{"1":"22","3":"10"}},{"t":"case","label":"Copeland v. Stephens","cite":"106 Eng. Rep. 218","y":1818,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./106/218/","by":{"1":"21"}},{"t":"case","label":"Defiance Button Mach. Co. v. C & C Metal Prods. Corp.","cite":"759 F.2d 1053","y":1985,"url":"https://www.courtlistener.com/c/F.2d/759/1053/","by":{"1":"24"}},{"t":"case","label":"Enterprise Energy Corp. v. United States","cite":"50 F.3d 233","y":1995,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/50/233/","by":{"1":"17"}},{"t":"case","label":"Kokoszka v. Belford","cite":"417 U.S. 642","y":1974,"id":"1973/73-5265","sc":1,"by":{"1":"26"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"by":{"1":"30","2":"50"},"q":[{"src":"brief","b":1,"text":"‘must and can only be exercised within the confines of ’ the Bankruptcy Code.","cite":"571 U.S. 415, 421"},{"src":"brief","b":2,"text":"long held that whatever equitable powers remain in the bankruptcy courts must and can only be exercised within the confines of the Bankruptcy Code.","cite":"571 U.S. 415, 421"}]},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"by":{"1":"19, 20","2":"49"},"q":[{"src":"brief","b":1,"text":"‘set aside certain types of transfers and recapture the value of those avoided transfers for the benefit of the estate.’","cite":"138 S. Ct. 883, 888"},{"src":"brief","b":2,"text":"recapture the value of * * * avoided transfers for the benefit of the estate,","cite":"138 S. Ct. at 888"}]},{"t":"case","label":"Midland Funding, LLC v. Johnson","cite":"137 S. Ct. 1407","y":2017,"id":"2016/16-348","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"delicate balance of a debtor’s protections and obligations","cite":"137 S. Ct. 1407, 1415"}]},{"t":"case","label":"Nautilus, Inc. v. Biosig Instruments, Inc.","cite":"572 U.S. 898","y":2014,"id":"2013/13-369","sc":1,"by":{"1":"32","2":"23"},"q":[{"src":"brief","b":1,"text":"a court of review, not of first view.","cite":"572 U.S. 898, 913"},{"src":"brief","b":2,"text":"a court of review, not of first view.","cite":"572 U.S. 898, 913"}]},{"t":"case","label":"O’Neill v. Continental Airlines, Inc.","cite":"981 F.2d 1450","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/1450/","by":{"1":"18"}},{"t":"case","label":"Sparhawk v. Yerkes","cite":"142 U.S. 1","y":1891,"id":"scdb/1891-043","sc":1,"by":{"1":"21, 22"}},{"t":"case","label":"United States Trust Co. v. Wabash W. Ry. Co.","cite":"150 U.S. 287","y":1893,"id":"scdb/1893-040","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"an assignee or receiver is not bound to adopt the contracts, accept the leases, or otherwise step into the shoes of [the debtor], if, in his opinion, it would be unprofitable or undesirable to do so.","cite":"150 U.S. 287, 299"}]},{"t":"case","label":"Vass v. Conron Bros. Co.","cite":"59 F.2d 969","y":1932,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/59/969/","by":{"1":"22"}},{"t":"case","label":"Watson v. Merrill","cite":"136 F. 359","y":1905,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./136/359/","by":{"1":"21, 22"}},{"t":"law","label":"Pub. L. No. 100-506","url":"https://www.govinfo.gov/link/statute/102/2538","by":{"1":"6"}},{"t":"usc","label":"11 U.S.C. § 323","url":"https://www.law.cornell.edu/uscode/text/11/323","stext":{"head":"§323. Role and capacity of trustee","paras":[[0,"(a) The trustee in a case under this title is the representative of the estate."],[0,"(b) The trustee in a case under this title has capacity to sue and be sued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/323?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4, 16","2":"4"}},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","subs":["(a)","(g)","(g)(1)","(h)","(n)","(n)(1)","(n)(2)(B)","(d)","(d)(1)","(h)(1)","(h)(l)(B)","(h)(l)(C)","(h)(2)","(i)","(i)(1)","(i)(2)","(n)(1)(B)","(n)(2)","(n)(2)(C)"],"stext":{"head":"§365. Executory contracts and unexpired leases","paras":[[0,"(a) Except as provided in sections 765 and 766 of this title and in subsections (b), (c), and (d) of this section, the trustee, subject to the court's approval, may assume or reject any executory contract or unexpired lease of the debtor."],[0,"(b)(1) If there has been a default in an executory contract or unexpired lease of the debtor, the trustee may not assume such contract or lease unless, at the time of assumption of such contract or lease, the trustee—"],[1,"(A) cures, or provides adequate assurance that the trustee will promptly cure, such default other than a default that is a breach of a provision relating to the satisfaction of any provision (other than a penalty rate or penalty provision) relating to a default arising from any failure to perform nonmonetary obligations under an unexpired lease of real property, if it is impossible for the trustee to cure such default by performing nonmonetary acts at and after the time of assumption, except that if such default arises from a failure to operate in accordance with a nonresidential real property lease, then such default shall be cured by performance at and after the time of assumption in accordance with such lease, and pecuniary losses resulting from such default shall be compensated in accordance with the provisions of this paragraph;"],[1,"(B) compensates, or provides adequate assurance that the trustee will promptly compensate, a party other than the debtor to such contract or lease, for any actual pecuniary loss to such party resulting from such default; and"],[1,"(C) provides adequate assurance of future performance under such contract or lease."],[0,"(2) Paragraph (1) of this subsection does not apply to a default that is a breach of a provision relating to—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title;"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement; or"],[1,"(D) the satisfaction of any penalty rate or penalty provision relating to a default arising from any failure by the debtor to perform nonmonetary obligations under the executory contract or unexpired lease."],[0,"(3) For the purposes of paragraph (1) of this subsection and paragraph (2)(B) of subsection (f), adequate assurance of future performance of a lease of real property in a shopping center includes adequate assurance—"],[1,"(A) of the source of rent and other consideration due under such lease, and in the case of an assignment, that the financial condition and operating performance of the proposed assignee and its guarantors, if any, shall be similar to the financial condition and operating performance of the debtor and its guarantors, if any, as of the time the debtor became the lessee under the lease;"],[1,"(B) that any percentage rent due under such lease will not decline substantially;"],[1,"(C) that assumption or assignment of such lease is subject to all the provisions thereof, including (but not limited to) provisions such as a radius, location, use, or exclusivity provision, and will not breach any such provision contained in any other lease, financing agreement, or master agreement relating to such shopping center; and"],[1,"(D) that assumption or assignment of such lease will not disrupt any tenant mix or balance in such shopping center."],[0,"(4) Notwithstanding any other provision of this section, if there has been a default in an unexpired lease of the debtor, other than a default of a kind specified in paragraph (2) of this subsection, the trustee may not require a lessor to provide services or supplies incidental to such lease before assumption of such lease unless the lessor is compensated under the terms of such lease for any services and supplies provided under such lease before assumption of such lease."],[0,"(c) The trustee may not assume or assign any executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(1)(A) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to an entity other than the debtor or the debtor in possession, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"],[1,"(B) such party does not consent to such assumption or assignment; or"],[1,"(2) such contract is a contract to make a loan, or extend other debt financing or financial accommodations, to or for the benefit of the debtor, or to issue a security of the debtor; or"],[1,"(3) such lease is of nonresidential real property and has been terminated under applicable nonbankruptcy law prior to the order for relief."],[0,"(d)(1) In a case under chapter 7 of this title, if the trustee does not assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor within 60 days after the order for relief, or within such additional time as the court, for cause, within such 60-day period, fixes, then such contract or lease is deemed rejected."],[0,"(2) In a case under chapter 9, 11, 12, or 13 of this title, the trustee may assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor at any time before the confirmation of a plan but the court, on the request of any party to such contract or lease, may order the trustee to determine within a specified period of time whether to assume or reject such contract or lease."],[0,"(3) The trustee shall timely perform all the obligations of the debtor, except those specified in section 365(b)(2), arising from and after the order for relief under any unexpired lease of nonresidential real property, until such lease is assumed or rejected, notwithstanding section 503(b)(1) of this title. The court may extend, for cause, the time for performance of any such obligation that arises within 60 days after the date of the order for relief, but the time for performance shall not be extended beyond such 60-day period. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f) of this section. Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(4)(A) Subject to subparagraph (B), an unexpired lease of nonresidential real property under which the debtor is the lessee shall be deemed rejected, and the trustee shall immediately surrender that nonresidential real property to the lessor, if the trustee does not assume or reject the unexpired lease by the earlier of—"],[1,"(i) the date that is 120 days after the date of the order for relief; or"],[1,"(ii) the date of the entry of an order confirming a plan."],[0,"(B)(i) The court may extend the period determined under subparagraph (A), prior to the expiration of the 120-day period, for 90 days on the motion of the trustee or lessor for cause."],[0,"(ii) If the court grants an extension under clause (i), the court may grant a subsequent extension only upon prior written consent of the lessor in each instance."],[0,"(5) The trustee shall timely perform all of the obligations of the debtor, except those specified in section 365(b)(2), first arising from or after 60 days after the order for relief in a case under chapter 11 of this title under an unexpired lease of personal property (other than personal property leased to an individual primarily for personal, family, or household purposes), until such lease is assumed or rejected notwithstanding section 503(b)(1) of this title, unless the court, after notice and a hearing and based on the equities of the case, orders otherwise with respect to the obligations or timely performance thereof. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f). Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(e)(1) Notwithstanding a provision in an executory contract or unexpired lease, or in applicable law, an executory contract or unexpired lease of the debtor may not be terminated or modified, and any right or obligation under such contract or lease may not be terminated or modified, at any time after the commencement of the case solely because of a provision in such contract or lease that is conditioned on—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title; or"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement."],[0,"(2) Paragraph (1) of this subsection does not apply to an executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(A)(i) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to the trustee or to an assignee of such contract or lease, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/365?type=usc&year=mostrecent&link-type=html"},"by":{"1":"27, 27, 27, 27, 27, 4, 4, 4","2":"passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, passim, 32, 32, 32, 32, 32, 32"},"q":[{"src":"brief","b":1,"text":"constitutes a breach of such contract.","cite":"11 U.S.C. 365(g)"},{"src":"brief","b":1,"text":"immediately before the date of the filing of the [bankruptcy] petition.","cite":"11 U.S.C. 365(g)"},{"src":"brief","b":2,"text":"assume or reject any executory contract or unexpired lease.","cite":"11 U.S.C. 365(a)"},{"src":"brief","b":2,"text":"constitutes a breach of such contract * * * immediately before the date of the filing of the petition,","cite":"11 U.S.C. 365(g)(1)"},{"src":"argument","who":"Ms. Spinelli","text":"Chief Justice, and may it please the Court: Section 365 of the Bankruptcy Code lets the trustee decide whether the estate will become a party to an executory contract of the debtor."},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"If, on the other hand, the copier has already been sold, then it's no longer property of the estate, and the other party does not have to return it. And that's exactly what -- the rule that we advocate for. So under Section 365 --"}]},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)"],"stext":{"head":"§541. Property of the estate","paras":[[0,"(a) The commencement of a case under section 301, 302, or 303 of this title creates an estate. Such estate is comprised of all the following property, wherever located and by whomever held:"],[1,"(1) Except as provided in subsections (b) and (c)(2) of this section, all legal or equitable interests of the debtor in property as of the commencement of the case."],[1,"(2) All interests of the debtor and the debtor's spouse in community property as of the commencement of the case that is—"],[2,"(A) under the sole, equal, or joint management and control of the debtor; or"],[2,"(B) liable for an allowable claim against the debtor, or for both an allowable claim against the debtor and an allowable claim against the debtor's spouse, to the extent that such interest is so liable."],[1,"(3) Any interest in property that the trustee recovers under section 329(b), 363(n), 543, 550, 553, or 723 of this title."],[1,"(4) Any interest in property preserved for the benefit of or ordered transferred to the estate under section 510(c) or 551 of this title."],[1,"(5) Any interest in property that would have been property of the estate if such interest had been an interest of the debtor on the date of the filing of the petition, and that the debtor acquires or becomes entitled to acquire within 180 days after such date—"],[2,"(A) by bequest, devise, or inheritance;"],[2,"(B) as a result of a property settlement agreement with the debtor's spouse, or of an interlocutory or final divorce decree; or"],[2,"(C) as a beneficiary of a life insurance policy or of a death benefit plan."],[1,"(6) Proceeds, product, offspring, rents, or profits of or from property of the estate, except such as are earnings from services performed by an individual debtor after the commencement of the case."],[1,"(7) Any interest in property that the estate acquires after the commencement of the case."],[0,"(b) Property of the estate does not include—"],[1,"(1) any power that the debtor may exercise solely for the benefit of an entity other than the debtor;"],[1,"(2) any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease before the commencement of the case under this title, and ceases to include any interest of the debtor as a lessee under a lease of nonresidential real property that has terminated at the expiration of the stated term of such lease during the case;"],[1,"(3) any eligibility of the debtor to participate in programs authorized under the Higher Education Act of 1965 (20 U.S.C. 1001 et seq.; 42 U.S.C. 2751 et seq.),1 or any accreditation status or State licensure of the debtor as an educational institution;"],[1,"(4) any interest of the debtor in liquid or gaseous hydrocarbons to the extent that—"],[2,"(A)(i) the debtor has transferred or has agreed to transfer such interest pursuant to a farmout agreement or any written agreement directly related to a farmout agreement; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 544(a)(3) of this title; or"],[2,"(B)(i) the debtor has transferred such interest pursuant to a written conveyance of a production payment to an entity that does not participate in the operation of the property from which such production payment is transferred; and"],[2,"(ii) but for the operation of this paragraph, the estate could include the interest referred to in clause (i) only by virtue of section 365 or 542 of this title;"],[1,"(5) funds placed in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(e) of the Internal Revenue Code of 1986); and"],[2,"(C) in the case of funds placed in all such accounts having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(6) funds used to purchase a tuition credit or certificate or contributed to an account in accordance with section 529(b)(1)(A) of the Internal Revenue Code of 1986 under a qualified State tuition program (as defined in section 529(b)(1) of such Code) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of the amounts paid or contributed to such tuition program was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were paid or contributed;"],[2,"(B) with respect to the aggregate amount paid or contributed to such program having the same designated beneficiary, only so much of such amount as does not exceed the total contributions permitted under section 529(b)(6) of such Code with respect to such beneficiary, as adjusted beginning on the date of the filing of the petition in a case under this title by the annual increase or decrease (rounded to the nearest tenth of 1 percent) in the education expenditure category of the Consumer Price Index prepared by the Department of Labor; and"],[2,"(C) in the case of funds paid or contributed to such program having the same designated beneficiary not earlier than 720 days nor later than 365 days before such date, only so much of such funds as does not exceed $5,000; 2"],[1,"(7) any amount—"],[2,"(A) withheld by an employer from the wages of employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title; or"],[2,"(B) received by an employer from employees for payment as contributions—"],[3,"(i) to—"],[4,"(I) an employee benefit plan that is subject to title I of the Employee Retirement Income Security Act of 1974 or under an employee benefit plan which is a governmental plan under section 414(d) of the Internal Revenue Code of 1986;"],[4,"(II) a deferred compensation plan under section 457 of the Internal Revenue Code of 1986; or"],[4,"(III) a tax-deferred annuity under section 403(b) of the Internal Revenue Code of 1986;"],[0,"except that such amount under this subparagraph shall not constitute disposable income, as defined in section 1325(b)(2); or"],[3,"(ii) to a health insurance plan regulated by State law whether or not subject to such title;"],[1,"(8) subject to subchapter III of chapter 5, any interest of the debtor in property where the debtor pledged or sold tangible personal property (other than securities or written or printed evidences of indebtedness or title) as collateral for a loan or advance of money given by a person licensed under law to make such loans or advances, where—"],[2,"(A) the tangible personal property is in the possession of the pledgee or transferee;"],[2,"(B) the debtor has no obligation to repay the money, redeem the collateral, or buy back the property at a stipulated price; and"],[2,"(C) neither the debtor nor the trustee have exercised any right to redeem provided under the contract or State law, in a timely manner as provided under State law and section 108(b);"],[1,"(9) any interest in cash or cash equivalents that constitute proceeds of a sale by the debtor of a money order that is made—"],[2,"(A) on or after the date that is 14 days prior to the date on which the petition is filed; and"],[2,"(B) under an agreement with a money order issuer that prohibits the commingling of such proceeds with property of the debtor (notwithstanding that, contrary to the agreement, the proceeds may have been commingled with property of the debtor),"],[1,"unless the money order issuer had not taken action, prior to the filing of the petition, to require compliance with the prohibition; or"],[1,"(10) funds placed in an account of a qualified ABLE program (as defined in section 529A(b) of the Internal Revenue Code of 1986) not later than 365 days before the date of the filing of the petition in a case under this title, but—"],[2,"(A) only if the designated beneficiary of such account was a child, stepchild, grandchild, or stepgrandchild of the debtor for the taxable year for which funds were placed in such account;"],[2,"(B) only to the extent that such funds—"],[3,"(i) are not pledged or promised to any entity in connection with any extension of credit; and"],[3,"(ii) are not excess contributions (as described in section 4973(h) of the Internal Revenue Code of 1986); and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/541?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4","2":"4"},"q":[{"src":"brief","b":2,"text":"all legal or equitable interests of the debtor in property as of the commencement of the case.","cite":"11 U.S.C. 541"}]},{"t":"usc","label":"11 U.S.C. § 544","url":"https://www.law.cornell.edu/uscode/text/11/544","by":{"1":"19"}},{"t":"usc","label":"11 U.S.C. § 546","url":"https://www.law.cornell.edu/uscode/text/11/546","subs":["(a)","(b)"],"by":{"1":"20, 20"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","subs":["(a)","(a)(1)(A)"],"by":{"1":"19, 20"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","subs":["(a)"],"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"recover, for the benefit of the estate, the property transferred","cite":"11 U.S.C. 550(a)"}]},{"t":"usc","label":"11 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/11/553","by":{"1":"19"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","subs":["(1)"],"by":{"1":"4, 4, 6, 15, 16, 26","2":"4"}},{"t":"usc","label":"11 U.S.C. § 1107","url":"https://www.law.cornell.edu/uscode/text/11/1107","subs":["(a)"],"by":{"1":"4","2":"4"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"1":"2","2":"8, 9, 53"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","stext":{"head":"§1127. Construction and definitions; intent of chapter","paras":[[0,"In the construction of this chapter, unless the contrary is plainly apparent from the context—"],[0,"The United States includes and embraces all territory which is under its jurisdiction and control."],[0,"The word \"commerce\" means all commerce which may lawfully be regulated by Congress."],[0,"The term \"principal register\" refers to the register provided for by sections 1051 to 1072 of this title, and the term \"supplemental register\" refers to the register provided for by sections 1091 to 1096 of this title."],[0,"The term \"person\" and any other word or term used to designate the applicant or other entitled to a benefit or privilege or rendered liable under the provisions of this chapter includes a juristic person as well as a natural person. The term \"juristic person\" includes a firm, corporation, union, association, or other organization capable of suing and being sued in a court of law."],[0,"The term \"person\" also includes the United States, any agency or instrumentality thereof, or any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States. The United States, any agency or instrumentality thereof, and any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The term \"person\" also includes any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The terms \"applicant\" and \"registrant\" embrace the legal representatives, predecessors, successors and assigns of such applicant or registrant."],[0,"The term \"Director\" means the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office."],[0,"The term \"related company\" means any person whose use of a mark is controlled by the owner of the mark with respect to the nature and quality of the goods or services on or in connection with which the mark is used."],[0,"The terms \"trade name\" and \"commercial name\" mean any name used by a person to identify his or her business or vocation."],[0,"The term \"trademark\" includes any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish his or her goods, including a unique product, from those manufactured or sold by others and to indicate the source of the goods, even if that source is unknown."],[0,"The term \"service mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish the services of one person, including a unique service, from the services of others and to indicate the source of the services, even if that source is unknown. Titles, character names, and other distinctive features of radio or television programs may be registered as service marks notwithstanding that they, or the programs, may advertise the goods of the sponsor."],[0,"The term \"certification mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person other than its owner, or"],[1,"(2) which its owner has a bona fide intention to permit a person other than the owner to use in commerce and files an application to register on the principal register established by this chapter,"],[0,"to certify regional or other origin, material, mode of manufacture, quality, accuracy, or other characteristics of such person's goods or services or that the work or labor on the goods or services was performed by members of a union or other organization."],[0,"The term \"collective mark\" means a trademark or service mark—"],[1,"(1) used by the members of a cooperative, an association, or other collective group or organization, or"],[1,"(2) which such cooperative, association, or other collective group or organization has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"and includes marks indicating membership in a union, an association, or other organization."],[0,"The term \"mark\" includes any trademark, service mark, collective mark, or certification mark."],[0,"The term \"use in commerce\" means the bona fide use of a mark in the ordinary course of trade, and not made merely to reserve a right in a mark. For purposes of this chapter, a mark shall be deemed to be in use in commerce—"],[1,"(1) on goods when—"],[2,"(A) it is placed in any manner on the goods or their containers or the displays associated therewith or on the tags or labels affixed thereto, or if the nature of the goods makes such placement impracticable, then on documents associated with the goods or their sale, and"],[2,"(B) the goods are sold or transported in commerce, and"],[1,"(2) on services when it is used or displayed in the sale or advertising of services and the services are rendered in commerce, or the services are rendered in more than one State or in the United States and a foreign country and the person rendering the services is engaged in commerce in connection with the services."],[0,"A mark shall be deemed to be \"abandoned\" if either of the following occurs:"],[1,"(1) When its use has been discontinued with intent not to resume such use. Intent not to resume may be inferred from circumstances. Nonuse for 3 consecutive years shall be prima facie evidence of abandonment. \"Use\" of a mark means the bona fide use of such mark made in the ordinary course of trade, and not made merely to reserve a right in a mark."],[1,"(2) When any course of conduct of the owner, including acts of omission as well as commission, causes the mark to become the generic name for the goods or services on or in connection with which it is used or otherwise to lose its significance as a mark. Purchaser motivation shall not be a test for determining abandonment under this paragraph."],[0,"The term \"colorable imitation\" includes any mark which so resembles a registered mark as to be likely to cause confusion or mistake or to deceive."],[0,"The term \"registered mark\" means a mark registered in the United States Patent and Trademark Office under this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, or the Act of March 19, 1920. The phrase \"marks registered in the Patent and Trademark Office\" means registered marks."],[0,"The term \"Act of March 3, 1881\", \"Act of February 20, 1905\", or \"Act of March 19, 1920\", means the respective Act as amended."],[0,"A \"counterfeit\" is a spurious mark which is identical with, or substantially indistinguishable from, a registered mark."],[0,"The term \"domain name\" means any alphanumeric designation which is registered with or assigned by any domain name registrar, domain name registry, or other domain name registration authority as part of an electronic address on the Internet."],[0,"The term \"Internet\" has the meaning given that term in section 230(f)(1) of title 47."],[0,"Words used in the singular include the plural and vice versa."],[0,"The intent of this chapter is to regulate commerce within the control of Congress by making actionable the deceptive and misleading use of marks in such commerce; to protect registered marks used in such commerce from interference by State, or territorial legislation; to protect persons engaged in such commerce against unfair competition; to prevent fraud and deception in such commerce by the use of reproductions, copies, counterfeits, or colorable imitations of registered marks; and to provide rights and remedies stipulated by treaties and conventions respecting trademarks, trade names, and unfair competition entered into between the United States and foreign nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1127?type=usc&year=mostrecent&link-type=html"},"by":{"1":"14","2":"9, 45, 58"},"q":[{"src":"brief","b":1,"text":"lose its significance as a mark.","cite":"15 U.S.C. 1127"}]},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"1":"2"}},{"t":"case","label":"Andrus v. Glover Constr. Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"by":{"2":"38"},"q":[{"src":"brief","b":2,"text":"Where Congress explicitly enumerates certain exceptions to a general prohibition, additional exceptions are not to be implied, in the absence of evidence of a contrary legislative intent.","cite":"446 U.S. 608, 616617"}]},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"by":{"2":"8"}},{"t":"case","label":"Bank of Am. Nat’l Tr. & Sav. Ass’n v. 203 N. LaSalle St. P’ship","cite":"526 U.S. 434","y":1999,"id":"1998/97-1418","sc":1,"by":{"2":"41"},"q":[{"src":"brief","b":2,"text":"preserving going concerns and maximizing property available to satisfy creditors.","cite":"526 U.S. 434, 453"}]},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"by":{"2":"42"},"q":[{"src":"brief","b":2,"text":"central policy of the Bankruptcy Code","cite":"496 U.S. 53, 58"}]},{"t":"case","label":"Church of Scientology v. United States","cite":"506 U.S. 9","y":1992,"id":"1992/91-946","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"impossible for the court to grant ‘any effectual relief’","cite":"506 U.S. 9, 12"}]},{"t":"case","label":"City Bank Farmers Tr. Co. v. Irving Tr. Co.","cite":"299 U.S. 433","y":1937,"id":"scdb/1936-079","sc":1,"by":{"2":"passim","3":"5"},"q":[{"src":"brief","b":2,"text":"mature[d] at or before the filing of the petition.","cite":"299 U.S. 433, 440"},{"src":"brief","b":2,"text":"a reorganization is the discharge of all demands of whatsoever sort, executory and contingent, presently due or to mature in the future.","cite":"299 U.S. at 438"}]},{"t":"case","label":"City of Covington v. Covington Landing L.P.","cite":"71 F.3d 1221","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/71/1221/","by":{"2":"29"}},{"t":"case","label":"Communist Party of U.S. v. Subversive Activities Control Bd.","cite":"367 U.S. 1","y":1961,"id":"1960/12","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"plainly insufficient to raise the issue.","cite":"367 U.S. 1, 34-35 n.10"}]},{"t":"case","label":"Dawn Donut Co. v. Hart’s Food Stores, Inc.","cite":"267 F.2d 358","y":1959,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/267/358/","by":{"2":"9, 53, 54, 58"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"[A]n actual controversy must be extant at all stages of review * * *. If an intervening circumstance deprives the plaintiff of a personal stake in the outcome of the lawsuit, * * * the action can no longer proceed and must be dismissed as moot.","cite":"569 U.S. 66, 71-72"}]},{"t":"case","label":"Gorenstein Enters., Inc. v. Quality Care-USA, Inc.","cite":"874 F.2d 431","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/874/431/","by":{"2":"59"},"q":[{"src":"argument","who":"Mr. Hallward-Driemeier","text":"-- have reminded me of the Seventh Circuit's decision in Gorenstein Enterprises v. Quality Care-USA, 874 F.2d 431, which holds that it does end the licensee's right to use the mark."},{"src":"argument","who":"Ms. Spinelli","text":"First, the Gorenstein case that counsel referred to does not hold that a trademark licensor can unilaterally terminate a license by ceasing to exercise quality control."}]},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"by":{"2":"39"}},{"t":"case","label":"Hugo Boss Fashions, Inc. v. Federal Ins. Co.","cite":"252 F.3d 608","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/252/608/","by":{"2":"55"},"q":[{"src":"brief","b":2,"text":"that the licensee is granted a bare right to use the trademark or patent being licensed without any right to exclude others.","cite":"252 F.3d 608, 617"}]},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"485 U.S. 176","y":1988,"id":"1987/86-495","sc":1,"by":{"2":"55"}},{"t":"case","label":"Kotler v. American Tobacco Co.","cite":"981 F.2d 7","y":1992,"url":"https://www.courtlistener.com/c/F.2d/981/7/","by":{"2":"27"}},{"t":"case","label":"Leatherman v. Tarrant Cty. Narcotics Intelligence & Coordination Unit","cite":"507 U.S. 163","y":1993,"id":"1992/91-1657","sc":1,"by":{"2":"38"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"by":{"2":"26"}},{"t":"case","label":"Macmahan Pharmacal Co. v. Denver Chem. Mfg. Co.","cite":"113 F. 468","y":1901,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./113/468/","by":{"2":"9"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"identify goods and services that they wish to purchase, as well as those they want to avoid.","cite":"137 S. Ct. 1744, 1751"}]},{"t":"case","label":"Miller v. Glenn Miller Prods.","cite":"454 F.3d 975","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/975/","by":{"2":"54"},"q":[{"src":"brief","b":2,"text":"because trademark law, rather than the contract itself, confers on the licensor the right and obligation to exercise quality control.","cite":"454 F.3d 975, 992"}]},{"t":"case","label":"Ohio v. Kovacs","cite":"469 U.S. 274","y":1985,"id":"1984/83-1020","sc":1,"by":{"2":"31, 42"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"to provide national protection for trademarks used in interstate and foreign commerce.","cite":"469 U.S. 189, 193"},{"src":"brief","b":2,"text":"secure to the owner of the mark the goodwill of his business and * * * protect the ability of consumers to distinguish among competing producers.","cite":"469 U.S. at 198"}]},{"t":"case","label":"Sharon Steel Corp. v. National Fuel Gas Distrib. Corp.","cite":"872 F.2d 36","y":1989,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/872/36/","by":{"2":"28"}},{"t":"case","label":"Silverstar Enters., Inc. v. Aday","cite":"537 F. Supp. 236","y":1982,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./537/236/","by":{"2":"54"},"q":[{"src":"brief","b":2,"text":"confers only the right to use the trademark.","cite":"537 F. Supp. 236, 239"}]},{"t":"case","label":"United Drug Co. v. Theodore Rectanus Co.","cite":"248 U.S. 90","y":1918,"id":"scdb/1918-017","sc":1,"by":{"2":"53"},"q":[{"src":"brief","b":2,"text":"[t]here is no such thing as property in a trade-mark except as a right appurtenant to an established business or trade in connection with which the mark is employed.","cite":"248 U.S. 90, 97"}]},{"t":"case","label":"Visa, U.S.A., Inc. v. Birmingham Tr. Nat’l Bank","cite":"696 F.2d 1371","y":1982,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/696/1371/","by":{"2":"53"}},{"t":"usc","label":"11 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/11/502","subs":["(c)(2)","(g)(1)"],"by":{"2":"32, 28, 29"}},{"t":"usc","label":"11 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/11/503","subs":["(b)(1)(A)"],"by":{"2":"28, 29"},"q":[{"src":"brief","b":2,"text":"afforded the highest priority on the debtor’s estate.","cite":"11 U.S.C. 503(b)(1)(A)"}]},{"t":"usc","label":"11 U.S.C. § 506","url":"https://www.law.cornell.edu/uscode/text/11/506","by":{"2":"56"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","by":{"2":"6"}},{"t":"usc","label":"11 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/11/542","by":{"2":"47"}},{"t":"usc","label":"11 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/11/552","subs":["(b)"],"by":{"2":"50"}},{"t":"usc","label":"11 U.S.C. § 1113","url":"https://www.law.cornell.edu/uscode/text/11/1113","subs":["(a)","(b)","(c)","(d)(2)","(f)"],"by":{"2":"35, 35, 35, 35, 35, 35, 35"},"q":[{"src":"brief","b":2,"text":"the balance of the equities clearly favors rejection.","cite":"11 U.S.C. 1113(a)"}]},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(1)"],"by":{"2":"35"}},{"t":"usc","label":"15 U.S.C. § 1058","url":"https://www.law.cornell.edu/uscode/text/15/1058","by":{"2":"9"}},{"t":"usc","label":"15 U.S.C. § 1059","url":"https://www.law.cornell.edu/uscode/text/15/1059","by":{"2":"9"}},{"t":"usc","label":"15 U.S.C. § 1060","url":"https://www.law.cornell.edu/uscode/text/15/1060","subs":["(a)(1)"],"by":{"2":"9, 53"},"q":[{"src":"brief","b":2,"text":"with the good will of the business in which the mark is used.","cite":"15 U.S.C. 1060(a)(1)"}]},{"t":"law","label":"Pub. L. No. 98-353","url":"https://www.govinfo.gov/link/statute/98/333","by":{"2":"6"}},{"t":"case","label":"Chafin v. Chafin","cite":"568 U.S. 165","y":2013,"id":"2012/11-1347","sc":1,"by":{"3":"21, 23"},"q":[{"src":"brief","b":3,"text":"his prospects of success are … not pertinent to the mootness inquiry.","cite":"568 U.S. at 174"},{"src":"brief","b":3,"text":"the fact that a defendant is insolvent does not moot a claim for damages.","cite":"568 U.S. at 175"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"it is impossible for a court to grant any effectual relief whatever","cite":"568 U. S. 165, 172"}]},{"t":"case","label":"Coy v. Title Guarantee & Trust Co.","cite":"198 F. 275","y":1912,"court":"D. Or.","url":"https://www.courtlistener.com/c/F./198/275/","by":{"3":"10"}},{"t":"case","label":"De Forest Radio Telephone Co. v. United States","cite":"273 U.S. 236","y":1927,"id":"scdb/1926-148","sc":1,"by":{"3":"20"},"q":[{"src":"brief","b":3,"text":"[a]ny language used by the owner of the patent … consent[ing] to [another’s] use of the patent in … selling it … constitutes a license.","cite":"273 U.S. 236, 241"}]},{"t":"case","label":"Florida Department of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"by":{"3":"15"}},{"t":"case","label":"Krebs Chrysler-Plymouth, Inc. v. Valley Motors, Inc.","cite":"141 F.3d 490","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/141/490/","by":{"3":"18"}},{"t":"case","label":"Page(s) Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"3":"14"},"q":[{"src":"brief","b":3,"text":"the expressio unius canon … can be overcome by ‘contrary indications that [the language] was probably not meant to signal any exclusion.’","cite":"568 U.S. 371, 381"},{"src":"brief","b":3,"text":"not … superfluous if Congress included it to remove doubt","cite":"568 U.S. at 385"}]},{"t":"case","label":"Reading Co. v. Brown","cite":"391 U.S. 471","y":1968,"id":"1967/127","sc":1,"by":{"3":"19"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","by":{"3":"13"}}]};